//! Kani harnesses at the component / `IEvictionPolicy` boundary.
//!
//! This is a CHILD module of the crate root, so it can read `EvictionState`'s
//! private `announced` latch and the `state` / `logger` fields generated by
//! `define_component!`. Wired from `src/lib.rs` with
//! `#[cfg(kani)] #[path = "../verif-kani/component_harnesses.rs"] mod component_harnesses;`
//! so all harness code lives outside `src/`.
//!
//! Geometry: the REAL component is built with `new_default()` (so the generated
//! interface map, the `RwLock<EvictionState>` and the per-pool `Mutex<Pool>` are
//! all in situ) with `RandomState::new` stubbed to a fixed `[0,0]` seed. Pools hold
//! 1-3 blocks so every invariant loop is covered at unwind 4. See
//! `pool_harnesses.rs` for why the sound bound is >= 6 and why the gate's
//! `--no-unwinding-checks` lever (bounded-shallow) is the affordable claim here.

#![allow(dead_code, unused_imports, unused_variables, unused_mut)]

use super::{EvictionPolicySessionListsComponent, EvictionState};
use interfaces::{
    BlockSemantics, CacheKey, EvictionHandle, EvictionPolicyError, IEvictionPolicy, ILogger, PoolId,
};
use std::collections::hash_map::RandomState;
use std::mem::transmute;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use crate::session_list::pool_harnesses::{
    active_at, check_inv, child_at, clock_of, has_key, ix_of, key_at, leaves_len, parent_at,
    session_at, slots_of, stamp_at,
};

/// Deterministic `RandomState` — defeats KD-HASHMAP-RANDOMSTATE.
pub fn concrete_state() -> RandomState {
    let keys: [u64; 2] = [0, 0];
    unsafe { transmute(keys) }
}

fn comp() -> Arc<EvictionPolicySessionListsComponent> {
    EvictionPolicySessionListsComponent::new_default()
}

fn sem(s: u64) -> BlockSemantics {
    BlockSemantics { session_id: s }
}

/// A symbolic pool id that is guaranteed NOT to name an existing pool.
fn any_bad_pool(existing: u32) -> PoolId {
    let p: PoolId = kani::any();
    kani::assume(p >= existing);
    p
}

/// A symbolic arena index in range for a <= 3 slot pool.
fn any_ix() -> u32 {
    let i: u32 = kani::any();
    kani::assume(i < 4);
    i
}


/// Faithful element-wise model of `core::ptr::swap_nonoverlapping`. The real
/// implementation swaps through fixed 8-byte chunks, so its inner loop runs
/// `size_of::<T>() / 8` times whatever the data size -- 6 iterations for `Node`,
/// which is the loop that puts unwinding checks out of reach here (MEASURED: one
/// `register` closes at unwind 6 in 253 s, and at unwind 4 with this model in
/// 177 s). The model performs exactly the same memory effect with a
/// `count`-length loop (`count` is 1 at every call site reached), so no unwind
/// budget is spent on a byte-chunking detail. Disclosed stub -> symbol *.
unsafe fn swap_nonoverlapping_model<T>(x: *mut T, y: *mut T, count: usize) {
    let mut i = 0usize;
    while i < count {
        let t = std::ptr::read(x.add(i));
        std::ptr::write(x.add(i), std::ptr::read(y.add(i)));
        std::ptr::write(y.add(i), t);
        i += 1;
    }
}

/// Counts the `info` announcements so "at most once" is observable.
struct CountingLogger {
    infos: AtomicUsize,
}

impl ILogger for CountingLogger {
    fn error(&self, _msg: &str) {}
    fn warn(&self, _msg: &str) {}
    fn info(&self, _msg: &str) {
        self.infos.fetch_add(1, Ordering::SeqCst);
    }
    fn debug(&self, _msg: &str) {}
}

