// EPSL-CREATE-POOL-STARTS-EMPTY
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_create_pool_starts_empty() {
    let c = comp();
    let p = c.create_pool();
    assert!(c.len(p) == 0);
    assert!(c.identify_next_to_evict(p).is_none());
    assert!(c.get_eviction_candidates(p, 4).is_empty());
    assert!(c.get_eviction_candidates(p, 0).is_empty());
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_create_pool_starts_empty__mutant() {
    // WRONG: claims a fresh domain already has something to evict.
    let c = comp();
    let p = c.create_pool();
    assert!(c.identify_next_to_evict(p).is_some());
}

// EPSL-CREATE-POOL-ISSUES-A-FRESH-SEQUENTIAL-IDENTIFIER
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_create_pool_issues_a_fresh_sequential_identifier() {
    let c = comp();
    let a = c.create_pool();
    let b = c.create_pool();
    let d = c.create_pool();
    // start at zero, count upwards, no gaps, no reuse
    assert!(a == 0);
    assert!(b == 1);
    assert!(d == 2);
    assert!(a != b && b != d && a != d);
    // the identifier handed back is the number of domains that existed before
    assert!(c.state.read().unwrap().pools.len() == 3);
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_create_pool_issues_a_fresh_sequential_identifier__mutant() {
    // WRONG: claims identifiers are reused.
    let c = comp();
    let a = c.create_pool();
    let b = c.create_pool();
    assert!(a == b);
}

// EPSL-CREATE-POOL-PRESERVES-EXISTING-POOLS
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_create_pool_preserves_existing_pools() {
    let c = comp();
    let pa = c.create_pool();
    let h1 = c.track(pa, 10, sem(1)).unwrap();
    let h2 = c.track(pa, 20, sem(1)).unwrap();
    let len_before = c.len(pa);
    let cands_before = c.get_eviction_candidates(pa, 4);
    let pb = c.create_pool();
    // pa still names the same domain with the same contents
    assert!(c.len(pa) == len_before);
    let cands_after = c.get_eviction_candidates(pa, 4);
    assert!(cands_after.len() == cands_before.len());
    for k in 0..cands_after.len() {
        assert!(cands_after[k] == cands_before[k]);
    }
    // its handles still work and still name their blocks
    assert!(c.touch(h1) == Ok(()));
    assert!(c.touch(h2) == Ok(()));
    assert!(pb != pa);
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_create_pool_preserves_existing_pools__mutant() {
    // WRONG: claims creating a domain empties the existing one.
    let c = comp();
    let pa = c.create_pool();
    c.track(pa, 10, sem(1)).unwrap();
    c.create_pool();
    assert!(c.len(pa) == 0);
}

// EPSL-CREATE-POOL-ANNOUNCES-AT-MOST-ONCE
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_create_pool_announces_at_most_once() {
    let c = comp();
    let lg = Arc::new(CountingLogger {
        infos: AtomicUsize::new(0),
    });
    let dynlg: Arc<dyn ILogger + Send + Sync> = lg.clone();
    assert!(c.logger.connect(dynlg).is_ok());
    c.create_pool();
    assert!(lg.infos.load(Ordering::SeqCst) == 1);
    assert!(c.state.read().unwrap().announced);
    c.create_pool();
    c.create_pool();
    // however many domains are created, the one-off announcement fired once
    assert!(lg.infos.load(Ordering::SeqCst) == 1);
    assert!(c.state.read().unwrap().announced);
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_create_pool_announces_at_most_once__mutant() {
    // WRONG: claims the announcement fires once per domain.
    let c = comp();
    let lg = Arc::new(CountingLogger {
        infos: AtomicUsize::new(0),
    });
    let dynlg: Arc<dyn ILogger + Send + Sync> = lg.clone();
    assert!(c.logger.connect(dynlg).is_ok());
    c.create_pool();
    c.create_pool();
    assert!(lg.infos.load(Ordering::SeqCst) == 2);
}

// EPSL-ANNOUNCE-LATCH-SET-ONLY-WITH-A-LOGGER
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_announce_latch_set_only_with_a_logger() {
    let c = comp();
    // no logger attached: the latch is NOT consumed, however many domains are made
    c.create_pool();
    c.create_pool();
    assert!(!c.state.read().unwrap().announced);
    // and the announcement is still available once a logger arrives
    let lg = Arc::new(CountingLogger {
        infos: AtomicUsize::new(0),
    });
    let dynlg: Arc<dyn ILogger + Send + Sync> = lg.clone();
    assert!(c.logger.connect(dynlg).is_ok());
    c.create_pool();
    assert!(lg.infos.load(Ordering::SeqCst) == 1);
    assert!(c.state.read().unwrap().announced);
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
