// EPSL-POOL-COUNT-ASSUMED-BELOW-U32-MAX
#[kani::proof]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_pool_count_assumed_below_u32_max() {
    // The identifier is `state.pools.len() as u32`. Under the documented
    // assumption (fewer than u32::MAX domains) the cast is injective, so two
    // distinct domain counts can never yield the same identifier.
    let n: usize = kani::any();
    let m: usize = kani::any();
    kani::assume(n < u32::MAX as usize);
    kani::assume(m < u32::MAX as usize);
    kani::assume(n != m);
    assert!((n as u32) != (m as u32));
    assert!((n as u32) as usize == n);
}

#[kani::proof]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_pool_count_assumed_below_u32_max__mutant() {
    // WRONG: drops the assumption, so identifiers can repeat.
    let n: usize = kani::any();
    let m: usize = kani::any();
    kani::assume(n != m);
    assert!((n as u32) != (m as u32));
}

