// EPSL-TRACK-RETURNS-USABLE-HANDLE
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_track_returns_usable_handle() {
    let c = comp();
    let p = c.create_pool();
    let h = c.track(p, 10, sem(1)).unwrap();
    // the handle carries the domain the caller named plus the storage position
    assert!(h.pool_id() == p);
    assert!(h.index() == 0);
    assert!(h == EvictionHandle::new(p, 0));
    // and those two pieces are exactly what a later refresh / stop-tracking uses
    assert!(c.touch(h) == Ok(()));
    assert!(c.remove(h) == Ok(()));
    assert!(c.len(p) == 0);
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_track_returns_usable_handle__mutant() {
    // WRONG: claims the handle names a different domain.
    let c = comp();
    let p = c.create_pool();
    let q = c.create_pool();
    let h = c.track(p, 10, sem(1)).unwrap();
    assert!(h.pool_id() == q);
}

