// EPSL-TRACK-NEVER-REPORTS-INVALID-HANDLE
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_track_never_reports_invalid_handle() {
    let c = comp();
    c.create_pool();
    let p: PoolId = kani::any();
    kani::assume(p < 3); // covers the one live domain and two unknown ones
    let r = c.track(p, 10, sem(1));
    match r {
        Ok(_) => assert!(p == 0),
        Err(EvictionPolicyError::InvalidPool(id)) => assert!(id == p),
        Err(EvictionPolicyError::InvalidHandle) => assert!(false),
    }
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_track_never_reports_invalid_handle__mutant() {
    // WRONG: claims registration reports the invalid-handle error.
    let c = comp();
    c.create_pool();
    assert!(c.track(5, 10, sem(1)) == Err(EvictionPolicyError::InvalidHandle));
}

// EPSL-TRACK-KEYS-ARE-SCOPED-TO-ONE-POOL
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_track_keys_are_scoped_to_one_pool() {
    let c = comp();
    let pa = c.create_pool();
    let pb = c.create_pool();
    // the SAME key tracked independently in two domains
    let ha = c.track(pa, 10, sem(1)).unwrap();
    let hb = c.track(pb, 10, sem(9)).unwrap();
    assert!(ha != hb);
    assert!(ha.pool_id() == pa && hb.pool_id() == pb);
    assert!(c.len(pa) == 1 && c.len(pb) == 1);
    // each domain holds its own block for that key, with its own session and place
    let ga = c.state.read().unwrap();
    {
        let a = ga.pools[pa as usize].lock().unwrap();
        let b = ga.pools[pb as usize].lock().unwrap();
        let ia = ix_of(&a, 10);
        let ib = ix_of(&b, 10);
        assert!(session_at(&a, ia) == 1);
        assert!(session_at(&b, ib) == 9);
    }
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_track_keys_are_scoped_to_one_pool__mutant() {
    // WRONG: claims the second domain treats the key as already tracked.
    let c = comp();
    let pa = c.create_pool();
    let pb = c.create_pool();
    c.track(pa, 10, sem(1)).unwrap();
    c.track(pb, 10, sem(9)).unwrap();
    assert!(c.len(pb) == 0);
}

