// EPSL-HANDLE-OPERATIONS-REJECT-UNKNOWN-DOMAIN
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_handle_operations_reject_unknown_domain() {
    let c = comp();
    let p = c.create_pool();
    c.track(p, 10, sem(1)).unwrap();
    let bad = any_bad_pool(1);
    let h = EvictionHandle::new(bad, any_ix());
    assert!(c.touch(h) == Err(EvictionPolicyError::InvalidPool(bad)));
    assert!(c.remove(h) == Err(EvictionPolicyError::InvalidPool(bad)));
    assert!(c.batch_touch(&[h]) == Err(EvictionPolicyError::InvalidPool(bad)));
    // nothing changed
    assert!(c.len(p) == 1);
}

