// EPSL-BATCH-TOUCH-REFRESHES-EVERY-BLOCK
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_batch_touch_refreshes_every_block() {
    let c = comp();
    let p = c.create_pool();
    let ha = c.track(p, 10, sem(1)).unwrap();
    let hb = c.track(p, 20, sem(2)).unwrap();
    let hc = c.track(p, 30, sem(3)).unwrap();
    // refresh the two OLDEST in one call; every member must be refreshed, not
    // just the first or the last
    assert!(c.batch_touch(&[ha, hb]) == Ok(()));
    let g = c.state.read().unwrap();
    let pool = g.pools[p as usize].lock().unwrap();
    let ia = ix_of(&pool, 10);
    let ib = ix_of(&pool, 20);
    let ic = ix_of(&pool, 30);
    assert!(stamp_at(&pool, ia) > stamp_at(&pool, ic));
    assert!(stamp_at(&pool, ib) > stamp_at(&pool, ic));
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_batch_touch_refreshes_every_block__mutant() {
    // WRONG: claims only the first member of the group is refreshed, so 20 would
    // still be older than 30.
    let c = comp();
    let p = c.create_pool();
    let ha = c.track(p, 10, sem(1)).unwrap();
    let hb = c.track(p, 20, sem(2)).unwrap();
    c.track(p, 30, sem(3)).unwrap();
    assert!(c.batch_touch(&[ha, hb]) == Ok(()));
    assert!(c.identify_next_to_evict(p) == Some(20));
}

// EPSL-BATCH-TOUCH-MATCHES-ONE-AT-A-TIME
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_batch_touch_matches_one_at_a_time() {
    // Two independent domains driven identically: one batched, one one-at-a-time.
    let c = comp();
    let pa = c.create_pool();
    let pb = c.create_pool();
    let a1 = c.track(pa, 10, sem(1)).unwrap();
    let a2 = c.track(pa, 20, sem(2)).unwrap();
    let b1 = c.track(pb, 10, sem(1)).unwrap();
    let b2 = c.track(pb, 20, sem(2)).unwrap();
    // a duplicate mention must end up with the recency of its LAST mention
    assert!(c.batch_touch(&[a1, a2, a1]) == Ok(()));
    assert!(c.touch(b1) == Ok(()));
    assert!(c.touch(b2) == Ok(()));
    assert!(c.touch(b1) == Ok(()));
    let ca = c.get_eviction_candidates(pa, 4);
    let cb = c.get_eviction_candidates(pb, 4);
    assert!(ca.len() == cb.len());
    for k in 0..ca.len() {
        assert!(ca[k] == cb[k]);
    }
    assert!(c.identify_next_to_evict(pa) == c.identify_next_to_evict(pb));
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_batch_touch_matches_one_at_a_time__mutant() {
    // WRONG: claims a duplicate mention keeps the recency of its FIRST mention,
    // so 10 would be evicted before 20.
    let c = comp();
    let p = c.create_pool();
    let h1 = c.track(p, 10, sem(1)).unwrap();
    let h2 = c.track(p, 20, sem(2)).unwrap();
    assert!(c.batch_touch(&[h1, h2, h1]) == Ok(()));
    assert!(c.identify_next_to_evict(p) == Some(10));
}

// EPSL-BATCH-TOUCH-TOUCHES-NOTHING-ELSE
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_batch_touch_touches_nothing_else() {
    let c = comp();
    let p = c.create_pool();
    let q = c.create_pool();
    let ha = c.track(p, 10, sem(1)).unwrap();
    let hb = c.track(p, 20, sem(2)).unwrap();
    let hq = c.track(q, 30, sem(3)).unwrap();
    let (sb, sq, lp, lq) = {
        let g = c.state.read().unwrap();
        let a = g.pools[p as usize].lock().unwrap();
        let b = g.pools[q as usize].lock().unwrap();
        let ib = ix_of(&a, 20);
        let iq = ix_of(&b, 30);
        (
            stamp_at(&a, ib),
            stamp_at(&b, iq),
            a.len(),
            b.len(),
        )
    };
    assert!(c.batch_touch(&[ha]) == Ok(()));
    let g = c.state.read().unwrap();
    let a = g.pools[p as usize].lock().unwrap();
    let b = g.pools[q as usize].lock().unwrap();
    let ib = ix_of(&a, 20);
    let iq = ix_of(&b, 30);
    // a block not named in the group keeps its recency; nothing is added/removed
    assert!(stamp_at(&a, ib) == sb);
    assert!(stamp_at(&b, iq) == sq);
    assert!(a.len() == lp);
    assert!(b.len() == lq);
    assert!(parent_at(&a, ib).is_none());
}

