// EPSL-BATCH-TOUCH-RELOCKS-WHEN-THE-POOL-CHANGES
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_batch_touch_relocks_when_the_pool_changes() {
    let c = comp();
    let pa = c.create_pool();
    let pb = c.create_pool();
    let a1 = c.track(pa, 10, sem(1)).unwrap();
    let a2 = c.track(pa, 11, sem(2)).unwrap();
    let b1 = c.track(pb, 20, sem(1)).unwrap();
    // a group that ALTERNATES domains: pa, pb, pa -> the component must change
    // domain on every step and each block is refreshed in its own domain
    assert!(c.batch_touch(&[a1, b1, a2]) == Ok(()));
    let g = c.state.read().unwrap();
    let a = g.pools[pa as usize].lock().unwrap();
    let b = g.pools[pb as usize].lock().unwrap();
    let i10 = ix_of(&a, 10);
    let i11 = ix_of(&a, 11);
    let i20 = ix_of(&b, 20);
    // pa's clock advanced twice, pb's once -- each in its own domain
    assert!(clock_of(&a) == 4);
    assert!(clock_of(&b) == 2);
    assert!(stamp_at(&a, i11) > stamp_at(&a, i10));
    assert!(stamp_at(&b, i20) == 2);
}

