// EPSL-BATCH-TOUCH-SPANS-POOLS-ONE-LOCK-AT-A-TIME
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_batch_touch_spans_pools_one_lock_at_a_time() {
    let c = comp();
    let pa = c.create_pool();
    let pb = c.create_pool();
    let a1 = c.track(pa, 10, sem(1)).unwrap();
    let b1 = c.track(pb, 20, sem(1)).unwrap();
    let a2 = c.track(pa, 11, sem(2)).unwrap();
    // Going pa -> pb -> pa forces the component to RE-acquire pa's exclusive
    // access. `Mutex` is not reentrant, so completing at all witnesses that the
    // first guard was released before the next was taken: at no point were two
    // domain guards held together.
    assert!(c.batch_touch(&[a1, b1, a2]) == Ok(()));
    // both domains are still lockable afterwards, so no guard leaked
    let g = c.state.read().unwrap();
    assert!(g.pools[pa as usize].try_lock().is_ok());
    assert!(g.pools[pb as usize].try_lock().is_ok());
}

