// EPSL-BATCH-TOUCH-INVALID-HANDLE-IS-AN-ERROR  (divergent — refuted below)
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_batch_touch_invalid_handle_is_an_error() {
    // The spec obligation: a group holding a handle to a block that is no longer
    // tracked must report an error.
    let c = comp();
    let p = c.create_pool();
    let h1 = c.track(p, 10, sem(1)).unwrap();
    let h2 = c.track(p, 20, sem(2)).unwrap();
    assert!(c.remove(h2) == Ok(())); // h2 is now stale
    c.track(p, 30, sem(3)).unwrap(); // LIFO reuse of h2's slot
    let r = c.batch_touch(&[h1, h2]);
    kani::cover!(r == Ok(()), "the spec-forbidden success on a stale handle is reachable");
    assert!(r == Err(EvictionPolicyError::InvalidHandle));
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::stub(std::ptr::swap_nonoverlapping, swap_nonoverlapping_model)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn refute_epsl_batch_touch_invalid_handle_is_an_error() {
    // WITNESS: once the stale handle's slot has been reused the group refresh
    // silently succeeds and refreshes the block that now occupies the slot.
    let c = comp();
    let p = c.create_pool();
    let h1 = c.track(p, 10, sem(1)).unwrap();
    let h2 = c.track(p, 20, sem(2)).unwrap();
    assert!(c.remove(h2) == Ok(()));
    // while the slot is empty the group refresh correctly errors
    assert!(c.batch_touch(&[h2]) == Err(EvictionPolicyError::InvalidHandle));
    let h3 = c.track(p, 30, sem(3)).unwrap();
    assert!(h3 == h2); // same slot handed out again
    assert!(c.batch_touch(&[h1, h2]) == Ok(())); // NO error, contrary to the spec
    let g = c.state.read().unwrap();
    let pool = g.pools[p as usize].lock().unwrap();
    let i30 = ix_of(&pool, 30);
    assert!(i30 == h2.index());
    assert!(stamp_at(&pool, i30) == 5); // key 30 was refreshed instead
}

// EPSL-INV-FAILED-OPERATIONS-CHANGE-NOTHING  (divergent — refuted below)
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_inv_failed_operations_change_nothing() {
    // The spec obligation: an operation that reports an error leaves the tracking
    // state exactly as it was.
    let c = comp();
    let p = c.create_pool();
    let h1 = c.track(p, 10, sem(1)).unwrap();
    let h2 = c.track(p, 20, sem(2)).unwrap();
    let before = c.get_eviction_candidates(p, 4);
    // a group whose SECOND member is bad
    let r = c.batch_touch(&[h1, EvictionHandle::new(any_bad_pool(1), 0)]);
    assert!(r.is_err());
    let after = c.get_eviction_candidates(p, 4);
    let changed = after.len() != before.len() || (after.len() > 0 && after[0] != before[0]);
    kani::cover!(changed, "a failed operation leaving partial state behind is reachable");
    assert!(after.len() == before.len());
    for k in 0..after.len() {
        assert!(after[k] == before[k]);
    }
}

#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::stub(std::ptr::swap_nonoverlapping, swap_nonoverlapping_model)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn refute_epsl_inv_failed_operations_change_nothing() {
    // WITNESS: `batch_touch` refreshes each handle in turn and returns at the
    // first bad one, so every earlier handle KEEPS its new recency and the
    // eviction order is permanently changed by a call the caller was told failed.
    let c = comp();
    let p = c.create_pool();
    let h1 = c.track(p, 10, sem(1)).unwrap();
    let h2 = c.track(p, 20, sem(2)).unwrap();
    assert!(c.get_eviction_candidates(p, 4)[0] == 10); // 10 is the next victim
    let r = c.batch_touch(&[h1, EvictionHandle::new(9, 0)]);
    assert!(r == Err(EvictionPolicyError::InvalidPool(9))); // reported FAILED ...
    assert!(c.get_eviction_candidates(p, 4)[0] == 20); // ... yet the order moved
    let g = c.state.read().unwrap();
    let pool = g.pools[p as usize].lock().unwrap();
    let i10 = ix_of(&pool, 10);
    assert!(stamp_at(&pool, i10) == 3); // partial effect persisted
    assert!(clock_of(&pool) == 3);
}

/// Discriminator: every SINGLE-handle operation does satisfy the invariant
/// (each validates before mutating), so the violation is isolated to
/// `batch_touch`'s mutate-as-you-go loop in `src/lib.rs:169-182`.
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::stub(std::ptr::swap_nonoverlapping, swap_nonoverlapping_model)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_inv_failed_operations_change_nothing__discriminator() {
    let c = comp();
    let p = c.create_pool();
    let h1 = c.track(p, 10, sem(1)).unwrap();
    let h2 = c.track(p, 20, sem(2)).unwrap();
    let before = c.get_eviction_candidates(p, 4);
    let bad = EvictionHandle::new(9, 0);
    assert!(c.touch(bad).is_err());
    assert!(c.remove(bad).is_err());
    assert!(c.track(9, 30, sem(3)).is_err());
    let after = c.get_eviction_candidates(p, 4);
    assert!(after.len() == before.len());
    for k in 0..after.len() {
        assert!(after[k] == before[k]);
    }
    let g = c.state.read().unwrap();
    let pool = g.pools[p as usize].lock().unwrap();
    assert!(clock_of(&pool) == 2); // no partial effect at all
}

