    let pb = c.create_pool();
    c.track(pa, 10, sem(1)).unwrap();
    let hb = c.track(pb, 20, sem(1)).unwrap();
    c.track(pb, 21, sem(1)).unwrap();
    let (lb, clockb) = {
        let g = c.state.read().unwrap();
        let b = g.pools[pb as usize].lock().unwrap();
        (b.len(), clock_of(&b))
    };
    c.clear_pool(pa);
    assert!(c.len(pa) == 0);
    // pb is untouched: blocks, chains, recency values, counter, size, identifier
    let g = c.state.read().unwrap();
