// EPSL-INV-DOMAINS-ARE-INDEPENDENT
#[kani::proof]
#[kani::stub(RandomState::new, concrete_state)]
#[kani::unwind(4)]
#[kani::solver(minisat)]
fn verify_epsl_inv_domains_are_independent() {
    let c = comp();
    let pa = c.create_pool();
    let pb = c.create_pool();
    let ha = c.track(pa, 10, sem(1)).unwrap();
    let hb = c.track(pb, 10, sem(1)).unwrap(); // SAME key, other domain
    let (lb, clockb, sb) = {
        let g = c.state.read().unwrap();
        let b = g.pools[pb as usize].lock().unwrap();
        let i = ix_of(&b, 10);
        (b.len(), clock_of(&b), stamp_at(&b, i))
    };
    // a symbolic operation on pa
    let sel: u8 = kani::any();
    kani::assume(sel < 5);
    match sel {
        0 => {
            c.track(pa, 40, sem(2)).unwrap();
        }
        1 => {
            let _ = c.touch(ha);
        }
        2 => {
            let _ = c.remove(ha);
        }
        3 => {
            let _ = c.identify_next_to_evict(pa);
        }
        _ => c.clear_pool(pa),
    }
    // pb is completely unchanged, and a victim is only chosen from pb's blocks
    let g = c.state.read().unwrap();
    let b = g.pools[pb as usize].lock().unwrap();
    let i = ix_of(&b, 10);
    assert!(b.len() == lb);
    assert!(clock_of(&b) == clockb);
    assert!(stamp_at(&b, i) == sb);
    drop(b);
    drop(g);
    assert!(c.len(pb) == lb);
    assert!(c.identify_next_to_evict(pb) == Some(10));
}

